            ("\\u80000000", "1 [?]\n", "1 1 1 1 ?\n", "1 [?]\n", "before\n[?]\n", "awk: warning: invalid `\\u' escape sequence\n"),
            ("\\uffffffff", "1 [?]\n", "1 1 1 1 ?\n", "1 [?]\n", "before\n[?]\n", "awk: warning: invalid `\\u' escape sequence\n"),
            ("\\U0001f600", "9 [U0001f600]\n", "9 1 1 1 U0001f600\n", "1 [U0001f600]\n", "before\n[U0001f600]\n", "awk: warning: escape sequence `\\U' treated as plain `U'\n"),
            ("\\u-41", "4 [u-41]\n", "4 1 1 1 u-41\n", "1 [u-41]\n", "before\n[u-41]\n", "awk: warning: no hex digits in `\\u' escape sequence\n"),
            ("\\u{41}", "5 [u{41}]\n", "5 1 1 1 u{41}\n", "1 [u{41}]\n", "before\n[u{41}]\n", "awk: warning: no hex digits in `\\u' escape sequence\n"),
            ("\\u005c", "1 [\\]\n", "1 1 1 1 \\\n", "1 [\\]\n", "before\n[\\]\n", ""),
            ("\\u005cq", "2 [\\q]\n", "2 1 1 1 \\q\n", "1 [\\q]\n", "before\n[\\q]\n", ""),
            ("\\u0041\\n", "2 [A\n]\n", "2 1 1 1 A\n\n", "1 [A\n]\n", "before\n[A\n]\n", ""),
            ("\\x", "1 [x]\n", "1 1 1 1 x\n", "1 [x]\n", "before\n[x]\n", "awk: warning: no hex digits in `\\x' escape sequence\n"),
            ("\\x41", "1 [A]\n", "1 1 1 1 A\n", "1 [A]\n", "before\n[A]\n", ""),
            ("\\x4142", "3 [A42]\n", "3 1 1 1 A42\n", "1 [A42]\n", "before\n[A42]\n", ""),
            ("\\000", "1 [\u0000]\n", "1 1 1 1 \u0000\n", "1 [\u0000]\n", "before\n[\u0000]\n", ""),
            ("\\101", "1 [A]\n", "1 1 1 1 A\n", "1 [A]\n", "before\n[A]\n", ""),
            ("\\n", "1 [\n]\n", "1 1 1 1 \n\n", "1 [\n]\n", "before\n[\n]\n", ""),
            ("\\\\u0041", "6 [\\u0041]\n", "6 1 1 1 \\u0041\n", "1 [\\u0041]\n", "before\n[\\u0041]\n", ""),
        ];

        var number = 0;
        for (var profile = 0; profile < profiles.Length; profile++)
        {
            foreach (var (form, before, after) in forms)
            {
                for (var variant = 0; variant < variantsPerProfile; variant++)
                {
                    var row = expectations[profile * variantsPerProfile + variant];
                    var program = before + row.Escape + after;
                    var suffix = FormattableString.Invariant($"{form}-{number++:D4}");
                    string[] arguments = profile == 0 ? [program] : [profiles[profile], program];
                    var output = form switch
                    {
                        "value" => row.Value,
                        "operations" => row.Operations,
                        "array" => row.Array,
                        "failure" => row.BeforeFailure,
                        _ => "ok\n"
                    };
                    var fails = form == "failure";
                    var diagnostic = fails ? row.Warning + "awk: division by zero attempted\n" : row.Warning;
                    yield return UnicodeStringCase(suffix, arguments, output, diagnostic, fails ? 2 : 0);
                }
            }
        }
    }

    private static AwkGoldenCase UnicodeStringCase(string suffix, string[] arguments, string output, string diagnostic, int exitCode) =>
        AwkGoldenCaseBuilder.Create("unicode-string-" + suffix, arguments, [])
            .WithStdOut(output).WithStdErr(diagnostic).ExitsWith(exitCode).Build();
}
